"""Tests for Gmail 429/5xx exponential backoff (FR-ING-013) and Node AES-256-GCM known-answer (C4)."""
from __future__ import annotations

import logging
import unittest

import httpx

from ingestion.crypto import decrypt, derive_master_key, encrypt
from ingestion.gmail_client import GmailClient
from ingestion.logging_ import JsonFormatter
from ingestion.providers.base import InvalidGrantError, ProviderFetchError

# Ciphertexts generated by Node.js backend/src/services/crypto.js using key '0' * 64
NODE_KEY_HEX = "0" * 64
NODE_CIPHERTEXT_TOKEN = "+G1lKpyeSq0D0D1N7BafAiTpDXqUSDEiLr6PYdp1wYgt51F7XJxHG66MAVmzM9iAglXpRX/ANbN0TRMQRg=="
NODE_CIPHERTEXT_DEMO = "DGlvZDvE9/8jmCDf3THmAeOSVLeQjuOyyRiBP1D7ok6gZUSQyWNVJmpMM4+IbJ4ytCnMNuI12Go="


class TestCryptoAndBackoff(unittest.TestCase):
    def test_node_known_answer_decryption_and_round_trip(self) -> None:
        key = derive_master_key(NODE_KEY_HEX + "\n")
        self.assertEqual(decrypt(NODE_CIPHERTEXT_TOKEN, key), "1//0g-secep-test-refresh-token-v1")
        self.assertEqual(decrypt(NODE_CIPHERTEXT_DEMO, key), "demo-mailbox-no-google-token")

        ct = encrypt("round-trip-secret", key)
        self.assertEqual(decrypt(ct, key), "round-trip-secret")

        # Passphrase fallback (step 4)
        dev_key = derive_master_key("dev-passphrase")
        self.assertEqual(len(dev_key), 32)

    def test_429_retry_after_2_logs_wait_and_gives_up_after_5_attempts(self) -> None:
        attempts = 0
        waits: list[float] = []

        def handler(request: httpx.Request) -> httpx.Response:
            nonlocal attempts
            attempts += 1
            return httpx.Response(429, headers={"Retry-After": "2"}, json={"error": "rateLimitExceeded"})

        transport = httpx.MockTransport(handler)
        http_client = httpx.Client(transport=transport)
        client = GmailClient("cid", "csec", http_client=http_client, sleep_fn=waits.append)

        logger = logging.getLogger("ingestion.gmail_client")
        records: list[str] = []

        class ListHandler(logging.Handler):
            def emit(self, record: logging.LogRecord) -> None:
                records.append(JsonFormatter().format(record))

        lh = ListHandler()
        logger.addHandler(lh)
        old_level = logger.level
        logger.setLevel(logging.WARNING)
        try:
            with self.assertRaises(ProviderFetchError) as ctx:
                client.get_profile_history_id("tok", mailbox_id="mb-429")
            self.assertEqual(ctx.exception.http_status, 429)
            self.assertEqual(attempts, 5)
            self.assertEqual(waits, [2.0, 2.0, 2.0, 2.0])
            self.assertEqual(len(records), 4)
            for line in records:
                self.assertIn('"wait_s":2.0', line)
                self.assertIn('"http_status":429', line)
        finally:
            logger.removeHandler(lh)
            logger.setLevel(old_level)
            client.close()

    def test_invalid_grant_raises_invalid_grant_error(self) -> None:
        def handler(request: httpx.Request) -> httpx.Response:
            return httpx.Response(400, json={"error": "invalid_grant"})

        http_client = httpx.Client(transport=httpx.MockTransport(handler))
        client = GmailClient("cid", "csec", http_client=http_client)
        try:
            with self.assertRaises(InvalidGrantError):
                client.refresh_access_token("bad-refresh-tok", mailbox_id="mb-err")
        finally:
            client.close()


if __name__ == "__main__":
    unittest.main()
